They run the function, but they cannot change this, because the arrow has no this to change. To use a chosen this, write a normal function and bind it.

code:
const owner = { name: 'cart' };
const arrow = () => typeof this;
function normal() {
  return this.name;
}
console.log(arrow.call(owner));
console.log(normal.call(owner));
const bound = normal.bind(owner);
console.log(bound());

