The arrow is created inside the constructor, so the this it borrows is the instance being built, and it keeps that reference. Pull a normal method off the object instead and this is lost, which is the difference the arrow was hiding.

code:
class Checkout {
  constructor(total) {
    this.total = total;
    this.getTotal = () => this.total;
  }
  withTax(rate) {
    return this.total * (1 + rate);
  }
}
const c = new Checkout(100);
const asCallback = c.getTotal;
console.log(asCallback());
console.log(c.withTax(0.2));
console.log(c.getTotal === c.getTotal);

